1	/**
2	 * The `install` stage: resolve the lane's own closure, under declared policy.
3	 *
4	 * Spike C measured two npm decisions on the first unseen application and named
5	 * them as manual residue: "Two operator decisions per application before the
6	 * first build. Both are mechanisable as policy, and both are today unwritten
7	 * judgment" (`evidence/spikes/thin-wrapper-cost/verdict.json`, finding C3). The
8	 * first was a 2020 lockfile carrying an `https` tarball dependency, which modern
9	 * npm refuses with `EALLOWREMOTE`; the second was install scripts, which modern
10	 * npm skips by default, so the tree installed "without its native build ever
11	 * being attempted".
12	 *
13	 * Both are policies here, not judgment. Each has a declared flag, each defaults
14	 * to *not applied*, and a closure that needs one it was not given is a named
15	 * refusal rather than an operator reading a wall of npm output and deciding. The
16	 * defaults are the honest ones: this flow does not widen a package manager's own
17	 * safety default on an operator's behalf, and it does not install a tree whose
18	 * native build was silently skipped and call it installed.
19	 *
20	 * The policy findings are read out of the lockfile before anything runs, so the
21	 * refusal arrives before the network is touched rather than after a failed
22	 * install.
23	 */
24	
25	import { execFile } from 'node:child_process';
26	import { readdir } from 'node:fs/promises';
27	import { promisify } from 'node:util';
28	import * as path from 'pathe';
29	import { parseURL } from 'ufo';
30	import { directoryExists, fileExists, readJsonFile } from './analyze.ts';
31	import { refuse } from './refusals.ts';
32	
33	const run = promisify(execFile);
34	
35	/** The registry npm resolves a plain dependency from. */
36	export const DEFAULT_REGISTRY_HOST = 'registry.npmjs.org';
37	
38	/** The lockfiles this stage can install from, in the order it looks for them. */
39	export const NPM_LOCKFILES: readonly string[] = Object.freeze([
40		'package-lock.json',
41		'npm-shrinkwrap.json',
42	]);
43	
44	/** Lockfiles that name a package manager this stage's policies do not cover. */
45	export const FOREIGN_LOCKFILES: Readonly<Record<string, string>> = Object.freeze({
46		'yarn.lock': 'yarn',
47		'pnpm-lock.yaml': 'pnpm',
48	});
49	
50	export type InstallPolicy = Readonly<{
51		/** Carry npm's `--allow-remote` allowance for non-registry tarballs. */
52		allowRemoteTarballs: boolean;
53		/** Run the closure's install scripts, so a native build is attempted. */
54		allowInstallScripts: boolean;
55		/** Skip them, as a declared decision rather than as npm's silent default. */
56		skipInstallScripts: boolean;
57		/**
58		 * Install through a peer-dependency conflict.
59		 *
60		 * The third policy, and the one this repository measured rather than
61		 * inherited: a lane whose manifest now declares a current build toolchain
62		 * beside an era application's own pins can fail npm's peer resolution
63		 * outright (`ERESOLVE`). Carrying the allowance is a decision about what the
64		 * lane's closure is allowed to be, so it is declared like the other two.
65		 */
66		allowPeerConflicts: boolean;
67	}>;
68	
69	export const DEFAULT_INSTALL_POLICY: InstallPolicy = Object.freeze({
70		allowRemoteTarballs: false,
71		allowInstallScripts: false,
72		skipInstallScripts: false,
73		allowPeerConflicts: false,
74	});
75	
76	export type LockfileFindings = Readonly<{
77		lockfile: string;
78		lockfileVersion: number;
79		/** Dependencies resolved from somewhere other than the npm registry. */
80		remoteTarballDependencies: readonly string[];
81		/** Packages the lockfile marks as carrying an install script. */
82		installScriptPackages: readonly string[];
83	}>;
84	
85	const INSTALL_NOT_ESTABLISHED: readonly string[] = Object.freeze([
86		'An install resolves a closure. It is not a build, and it is not evidence that the closure works: nothing here establishes that any package in it compiles or runs.',
87		'The policy findings are read from the lockfile. A lockfile that does not mark an install script, or that resolves through a mirror this reading does not recognise, yields a finding this stage did not make.',
88		'`installScriptPackages` counts packages the lockfile declares an install script for. Whether a given script would have built anything on this host is not established here.',
89		'`closure: resolve` means the lane manifest declares a build toolchain the recorded lockfile predates, so npm resolved rather than replayed. The application’s own pins still come from the lockfile; what was newly resolved is what the manifest rewrite added, and that resolution is not a pin this repository recorded.',
90	]);
91	
92	function hostOf(value: string): string | null {
93		if (!value.startsWith('http://') && !value.startsWith('https://')) return null;
94		const parsed = parseURL(value);
95		return parsed.host ?? null;
96	}
97	
98	/** Read the two policy-bearing facts out of an npm lockfile. */
99	export function readLockfileFindings(
100		lockfile: string,
101		document: Record<string, unknown>,
102	): LockfileFindings {
103		const remote = new Set<string>();
104		const scripts = new Set<string>();
105		const lockfileVersion =
106			typeof document.lockfileVersion === 'number' ? document.lockfileVersion : 1;
107		const packages = document.packages as Record<string, unknown> | undefined;
108		if (packages !== undefined)
109			for (const key of Object.keys(packages).sort()) {
110				const entry = packages[key] as Record<string, unknown> | undefined;
111				if (entry === undefined || entry === null) continue;
112				const resolved = typeof entry.resolved === 'string' ? entry.resolved : null;
113				const host = resolved === null ? null : hostOf(resolved);
114				if (host !== null && host !== DEFAULT_REGISTRY_HOST)
115					remote.add(`${key === '' ? '.' : key} <- ${resolved ?? ''}`);
116				if (entry.hasInstallScript === true) scripts.add(key === '' ? '.' : key);
117			}
118		const walk = (tree: Record<string, unknown> | undefined, prefix: string): void => {
119			if (tree === undefined || tree === null) return;
120			for (const name of Object.keys(tree).sort()) {
121				const entry = tree[name] as Record<string, unknown> | undefined;
122				if (entry === undefined || entry === null) continue;
123				const identifier = prefix === '' ? name : `${prefix}/${name}`;
124				const version = typeof entry.version === 'string' ? entry.version : '';
125				const resolved = typeof entry.resolved === 'string' ? entry.resolved : version;
126				const host = hostOf(resolved);
127				if (host !== null && host !== DEFAULT_REGISTRY_HOST)
128					remote.add(`${identifier} <- ${resolved}`);
129				if (entry.hasInstallScript === true) scripts.add(identifier);
130				walk(entry.dependencies as Record<string, unknown> | undefined, identifier);
131			}
132		};
133		walk(document.dependencies as Record<string, unknown> | undefined, '');
134		return Object.freeze({
135			lockfile,
136			lockfileVersion,
137			remoteTarballDependencies: Object.freeze([...remote].sort()),
138			installScriptPackages: Object.freeze([...scripts].sort()),
139		});
140	}
141	
142	/**
143	 * Whether the closure is replayed or resolved.
144	 *
145	 * `replay` is `npm ci`: the lockfile is installed exactly as recorded, and a
146	 * manifest that disagrees with it is an error. `resolve` is `npm install`, and
147	 * it is what a lane whose manifest this pipeline rewrote requires — the lane
148	 * declares a build toolchain the recorded lockfile predates, so there is no
149	 * recorded closure for it to replay. The application's own pins still come from
150	 * the lockfile; what is newly resolved is what the rewrite added.
151	 */
152	export type ClosureMode = 'replay' | 'resolve';
153	
154	export type InstallPlan = Readonly<{
155		packageManager: string;
156		lockfile: string;
157		closure: ClosureMode;
158		findings: LockfileFindings;
159		policy: InstallPolicy;
160		command: readonly string[];
161	}>;
162	
163	/**
164	 * Decide the install command for a lane, or refuse by name.
165	 *
166	 * Nothing runs here. The whole point is that every decision this stage would
167	 * otherwise ask an operator for is taken from the declared policy and the
168	 * lockfile before a registry is contacted.
169	 */
170	export async function planLaneInstall(
171		laneDir: string,
172		policy: InstallPolicy = DEFAULT_INSTALL_POLICY,
173		environment: NodeJS.ProcessEnv = process.env,
174		closure: ClosureMode = 'replay',
175	): Promise<InstallPlan> {
176		if (policy.allowInstallScripts && policy.skipInstallScripts)
177			refuse({
178				code: 'install.install-script-policy-conflicts',
179				message:
180					'Install: the install-script allowance and the install-script skip were both declared. They are opposite policies and this flow does not pick between two declarations.',
181				stage: 'install',
182				origin: 'pipeline',
183			});
184		if (environment.VERSIONLESS_NETWORK_MODE === 'offline')
185			refuse({
186				code: 'install.network-not-permitted',
187				message:
188					'Install: VERSIONLESS_NETWORK_MODE is offline, so this stage may not reach a registry. No closure was resolved and nothing was installed.',
189				stage: 'install',
190				origin: 'pipeline',
191			});
192		for (const name of Object.keys(FOREIGN_LOCKFILES).sort())
193			if (await fileExists(path.join(laneDir, name)))
194				refuse({
195					code: 'install.package-manager-not-npm',
196					message: `Install: the lane carries ${name}, so its closure is pinned by ${FOREIGN_LOCKFILES[name] ?? 'another package manager'}. The two policies this stage carries — the remote-tarball allowance and the install-script allowance — are npm policies, and this flow does not translate them onto another package manager.`,
197					stage: 'install',
198					origin: 'pipeline',
199				});
200		let lockfile: string | null = null;
201		for (const name of NPM_LOCKFILES)
202			if (lockfile === null && (await fileExists(path.join(laneDir, name)))) lockfile = name;
203		if (lockfile === null)
204			refuse({
205				code: 'install.lockfile-absent',
206				message: `Install: the lane carries none of ${NPM_LOCKFILES.join(', ')}, so there is no pinned closure to install. This flow installs a recorded closure rather than resolving a new one.`,
207				stage: 'install',
208				origin: 'pipeline',
209			});
210		const document = await readJsonFile(path.join(laneDir, lockfile));
211		if (document === null)
212			refuse({
213				code: 'install.lockfile-unreadable',
214				message: `Install: ${lockfile} is not readable as a JSON object, so the closure it pins cannot be read and no install policy can be checked against it.`,
215				stage: 'install',
216				origin: 'pipeline',
217			});
218		const findings = readLockfileFindings(lockfile, document);
219		if (findings.remoteTarballDependencies.length > 0 && !policy.allowRemoteTarballs)
220			refuse({
221				code: 'install.remote-tarball-policy-not-declared',
222				message: `Install: the lockfile resolves ${String(findings.remoteTarballDependencies.length)} dependency(ies) from outside ${DEFAULT_REGISTRY_HOST}, first ${findings.remoteTarballDependencies[0] ?? ''}. Modern npm refuses those with EALLOWREMOTE unless the remote-tarball allowance is declared. Declare --allow-remote-tarballs to carry that policy; this flow does not take the allowance on an operator's behalf.`,
223				stage: 'install',
224				origin: 'pipeline',
225			});
226		if (
227			findings.installScriptPackages.length > 0 &&
228			!policy.allowInstallScripts &&
229			!policy.skipInstallScripts
230		)
231			refuse({
232				code: 'install.install-script-policy-not-declared',
233				message: `Install: the lockfile declares ${String(findings.installScriptPackages.length)} package(s) carrying an install script, first ${findings.installScriptPackages[0] ?? ''}. Modern npm skips them by default, which produces a tree whose native build was never attempted. Declare --allow-install-scripts to run them or --skip-install-scripts to record the skip as a decision; this flow does not let the default stand unnamed.`,
234				stage: 'install',
235				origin: 'pipeline',
236			});
237		const command = [
238			'npm',
239			closure === 'replay' ? 'ci' : 'install',
240			'--no-audit',
241			'--no-fund',
242			...(policy.allowRemoteTarballs ? ['--allow-remote', 'all'] : []),
243			...(policy.allowInstallScripts ? ['--foreground-scripts'] : ['--ignore-scripts']),
244			...(policy.allowPeerConflicts ? ['--legacy-peer-deps'] : []),
245		];
246		return Object.freeze({
247			packageManager: 'npm',
248			lockfile,
249			closure,
250			findings,
251			policy,
252			command: Object.freeze(command),
253		});
254	}
255	
256	export type InstallRecord = Readonly<{
257		stage: 'install';
258		ran: boolean;
259		/** Why the stage did not run, when it did not. */
260		reason: string | null;
261		packageManager: string | null;
262		lockfile: string | null;
263		closure: ClosureMode | null;
264		policy: InstallPolicy;
265		remoteTarballDependencies: readonly string[];
266		installScriptPackages: readonly string[];
267		command: readonly string[] | null;
268		exitCode: number | null;
269		/** Packages present in the lane's installed closure afterwards. */
270		installedPackages: number | null;
271		notEstablished: readonly string[];
272	}>;
273	
274	/** The record for a stage the run did not ask for. */
275	export function installNotRequested(reason: string): InstallRecord {
276		return Object.freeze({
277			stage: 'install',
278			ran: false,
279			reason,
280			packageManager: null,
281			lockfile: null,
282			closure: null,
283			policy: DEFAULT_INSTALL_POLICY,
284			remoteTarballDependencies: Object.freeze([]),
285			installScriptPackages: Object.freeze([]),
286			command: null,
287			exitCode: null,
288			installedPackages: null,
289			notEstablished: INSTALL_NOT_ESTABLISHED,
290		});
291	}
292	
293	/** How many packages the lane's installed closure carries, or null. */
294	export async function installedPackageCount(laneDir: string): Promise<number | null> {
295		const modules = path.join(laneDir, 'node_modules');
296		if (!(await directoryExists(modules))) return null;
297		let count = 0;
298		for (const entry of await readdir(modules, { withFileTypes: true })) {
299			if (!entry.isDirectory() || entry.name === '.bin') continue;
300			if (!entry.name.startsWith('@')) {
301				count += 1;
302				continue;
303			}
304			for (const scoped of await readdir(path.join(modules, entry.name), { withFileTypes: true }))
305				if (scoped.isDirectory()) count += 1;
306		}
307		return count;
308	}
309	
310	/**
311	 * Run the install this stage planned.
312	 *
313	 * A non-zero exit here is a **defect**, not a refusal: the policies were
314	 * declared, the closure was pinned, and the install still failed. Scoring that
315	 * as a refusal would let a broken tree be counted as a named, expected outcome.
316	 */
317	export async function runLaneInstall(
318		laneDir: string,
319		policy: InstallPolicy = DEFAULT_INSTALL_POLICY,
320		environment: NodeJS.ProcessEnv = process.env,
321		closure: ClosureMode = 'replay',
322	): Promise<InstallRecord> {
323		const plan = await planLaneInstall(laneDir, policy, environment, closure);
324		const [binary, ...args] = plan.command as readonly [string, ...string[]];
325		try {
326			await run(binary, args, { cwd: laneDir, env: environment, maxBuffer: 64 * 1024 * 1024 });
327		} catch (error) {
328			const detail = error instanceof Error ? error.message : String(error);
329			/**
330			 * One npm failure is a policy question rather than a breakage: a peer
331			 * conflict is npm reporting that the closure it was asked for is not
332			 * one it will assemble by default. That is a decision, so it is a named
333			 * refusal an operator can count and answer with a flag. Every other
334			 * failure is a defect.
335			 */
336			if (detail.includes('ERESOLVE') && !policy.allowPeerConflicts)
337				refuse({
338					code: 'install.peer-resolution-policy-not-declared',
339					message: `Install: npm refused the lane closure with ERESOLVE — a peer dependency conflict between the application's own era pins and the build toolchain the lane now declares. Declare --allow-peer-conflicts to install through it, which is a decision about what the lane's closure may be, or change what the lane declares. This flow does not take that decision on an operator's behalf.`,
340					stage: 'install',
341					origin: 'pipeline',
342				});
343			throw new Error(
344				`install: ${plan.command.join(' ')} failed in the lane. This is a defect rather than a refusal: the declared policies were applied and the pinned closure still did not install. ${detail}`,
345			);
346		}
347		return Object.freeze({
348			stage: 'install',
349			ran: true,
350			reason: null,
351			packageManager: plan.packageManager,
352			lockfile: plan.lockfile,
353			closure: plan.closure,
354			policy,
355			remoteTarballDependencies: plan.findings.remoteTarballDependencies,
356			installScriptPackages: plan.findings.installScriptPackages,
357			command: plan.command,
358			exitCode: 0,
359			installedPackages: await installedPackageCount(laneDir),
360			notEstablished: INSTALL_NOT_ESTABLISHED,
361		});
362	}
