1	/**
2	 * The `--witness` stage of `migrate`.
3	 *
4	 * It is opt-in for exactly the reason `--install`, `--build`, `--ingest` and
5	 * `--era-cell` are: a run that did not ask for it gets a record saying the lane
6	 * was not witnessed, rather than a record whose silence a reader could take for
7	 * a lane that was. It is ordered after the build because there is nothing to
8	 * witness until something has been emitted.
9	 *
10	 * The stage invokes exactly the path `witness:real-app` invokes. It composes no
11	 * journey of its own and forks no runner: the driver selection, the serialized
12	 * replay and the locality gate are all the generic runner's.
13	 */
14	
15	import * as path from 'pathe';
16	import type { WitnessSynthesizedRealAppRecord } from '../../../core/src/receipts/witness-real-app.ts';
17	
18	export type WitnessRecord = Readonly<{
19		ran: boolean;
20		/** Why the stage did not run, when it did not. */
21		reason?: string;
22		journeySource?: WitnessSynthesizedRealAppRecord['journeySource'];
23		replayabilityRatio?: number;
24		journeysRun?: number;
25		digest?: string;
26		notEstablished: readonly string[];
27	}>;
28	
29	const NOT_REQUESTED_NOT_ESTABLISHED: readonly string[] = Object.freeze([
30		'The lane was not witnessed. Nothing in this record establishes that anything renders, that any route is reachable, or that any gesture the application offers still works after the migration.',
31	]);
32	
33	const RAN_NOT_ESTABLISHED: readonly string[] = Object.freeze([
34		'A witnessed lane is a lane whose declared journeys were replayed once each on this host, serialized. Nothing here establishes an outcome under concurrent load.',
35		'Where the journeys were synthesized, they were derived from the application own end-to-end suite or from a bounded loopback crawl. The replayability ratio in the record is a count of derived journeys that name a route to start from, not a measure of coverage.',
36	]);
37	
38	export function witnessNotRequested(reason: string): WitnessRecord {
39		return Object.freeze({ ran: false, reason, notEstablished: NOT_REQUESTED_NOT_ESTABLISHED });
40	}
41	
42	/**
43	 * Witness the built lane.
